10	  grok-cfg = import ./grok.nix { inherit lib grok; inherit (mcp) servers; };
11	  claude = pkgs.writeShellApplication {
12	    name = "claude";
13	    runtimeInputs = [ llm-agents.claude-code ];
14	    # `=` form is required: --mcp-config is variadic and would otherwise consume
15	    # subsequent positional args as additional config files.
16	    #
17	    # `--effort max` rather than CLAUDE_CODE_EFFORT_LEVEL=max: the env var is
18	    # consulted ahead of everything else and pins the session, so /effort just
19	    # refuses ("Not applied: CLAUDE_CODE_EFFORT_LEVEL=max overrides effort this
20	    # session"). The flag only seeds the session's starting level, leaving
21	    # /effort free to change it. The `effortLevel` setting is not an option
22	    # either: its schema stops at xhigh, so `max` cannot be persisted there.
23	    # Placed before "$@" because the last --effort wins, so an explicit
24	    # `claude --effort high` still overrides this default.
25	    text = ''exec claude --mcp-config=${mcp.claudeMcpConfig} --effort max "$@"'';
26	  };
27	  codex = pkgs.writeShellApplication {
28	    name = "codex";
29	    runtimeInputs = [ llm-agents.codex ];
30	    text = ''exec codex ${lib.concatStringsSep " " (mcp.codexArgs ++ codex-cfg.configArgs)} "$@"'';
31	  };
32	  agy = llm-agents.antigravity-cli;
33	  grok = llm-agents.grok;
