74	  home.activation.windowsterminal = lib.hm.dag.entryAfter ["writeBoundary"] ''
75	    # Glob over user profiles (LocalState is created lazily on WT's first
76	    # launch, so gating on it would silently no-op on freshly-imaged Windows
77	    # boxes where the user opened wsl from cmd.exe before ever opening WT).
78	    for user_dir in /mnt/c/Users/*; do
79	      [ -f "$user_dir/NTUSER.DAT" ] || continue
80	      [ -w "$user_dir" ] || continue
81	      wt_dir="$user_dir/AppData/Local/Packages/Microsoft.WindowsTerminal_8wekyb3d8bbwe/LocalState"
82	      mkdir -p "$wt_dir" || continue
83	      ${pkgs.gnused}/bin/sed 's/\x1b/\\u001b/g' ${../config/windows-terminal.json} \
84	        > "$wt_dir/settings.json"
85	    done
86	  '';
