102	      install -d "$user_dir/AppData/Local/chrome-devtools-mcp"
103	      install -m 0644 ${../config/windows/install-chrome-devtools-shortcut.ps1} \
104	        "$user_dir/AppData/Local/chrome-devtools-mcp/install-shortcut.ps1"
105	      ps1_win=$(/sbin/wslpath -w "$user_dir/AppData/Local/chrome-devtools-mcp/install-shortcut.ps1")
106	      "$powershell" -NoProfile -ExecutionPolicy Bypass -File "$ps1_win" || true
