110	  # FancyZones lives on the Windows side (PowerToys). Same pattern as
111	  # windowsterminal: push the repo copy onto every writable Windows profile.
112	  # applied-layouts.json is keyed by GPU-specific monitor-instance IDs, so a
113	  # blind overwrite would miss displays on another machine. Stamp the default
114	  # custom grid onto every device the target already knows; fall back to a
115	  # straight copy when PowerToys has not created the file yet.
116	  home.activation.fancyzones = lib.hm.dag.entryAfter ["writeBoundary"] ''
117	    fancyzones_src=${../config/windows/fancyzones}
118	    jq=${pkgs.jq}/bin/jq
119	    for user_dir in /mnt/c/Users/*; do
120	      [ -f "$user_dir/NTUSER.DAT" ] || continue
121	      [ -w "$user_dir" ] || continue
122	      fz_dir="$user_dir/AppData/Local/Microsoft/PowerToys/FancyZones"
123	      mkdir -p "$fz_dir" || continue
124	      for f in settings.json custom-layouts.json default-layouts.json \
125	               layout-hotkeys.json layout-templates.json; do
126	        install -m 0644 "$fancyzones_src/$f" "$fz_dir/$f"
127	      done
128	      dest="$fz_dir/applied-layouts.json"
129	      src="$fancyzones_src/applied-layouts.json"
130	      if [ -f "$dest" ] && "$jq" -e '."applied-layouts" | type == "array"' "$dest" >/dev/null 2>&1; then
131	        "$jq" --slurpfile defaults "$fancyzones_src/default-layouts.json" '
132	          ($defaults[0]."default-layouts"[0].layout) as $layout
133	          | ."applied-layouts" |= map(. + {"applied-layout": $layout})
134	        ' "$dest" > "$dest.tmp" && mv "$dest.tmp" "$dest"
135	        chmod 0644 "$dest"
136	      else
137	        install -m 0644 "$src" "$dest"
138	      fi
139	      pt_settings="$user_dir/AppData/Local/Microsoft/PowerToys/settings.json"
140	      if [ -f "$pt_settings" ] && [ -w "$pt_settings" ]; then
141	        "$jq" '.enabled.FancyZones = true' "$pt_settings" > "$pt_settings.tmp" \
142	          && mv "$pt_settings.tmp" "$pt_settings"
143	        chmod 0644 "$pt_settings"
144	      fi
145	    done
146	  '';
