269	  # Claude Code writes ~/.claude/settings.json itself: /effort, /model and
270	  # /config save defaults there, and an "always allow" answer appends to
271	  # permissions.allow. Each write is staged as a sibling temp file, so a
272	  # home.file symlink into the store fails the whole command with EROFS
273	  # ("Failed to set effort level: ... EROFS: read-only file system"). Install a
274	  # real, writable copy instead and merge this repo's keys over whatever Claude
275	  # Code has accumulated: the pins below win, its own keys survive. A key
276	  # dropped from config/claude/settings.json lingers in the copy until it is
277	  # deleted there by hand.
278	  home.activation.claudeSettings = lib.hm.dag.entryAfter ["linkGeneration"] ''
279	    settings="$HOME/.claude/settings.json"
280	    managed=${../config/claude/settings.json}
281	    install -d "$(dirname "$settings")"
282	    if [ -f "$settings" ] && [ ! -L "$settings" ]; then
283	      ${pkgs.jq}/bin/jq -s '.[0] * .[1]' "$settings" "$managed" > "$settings.new" \
284	        || cp "$managed" "$settings.new"
285	    else
286	      cp "$managed" "$settings.new"
287	    fi
288	    chmod 0644 "$settings.new"
289	    mv -f "$settings.new" "$settings"
290	  '';
