292	  # programs.git renders ~/.config/git/config into the store, but `git config
293	  # --global` -- what `git lfs install`, `gh auth setup-git` and git's own
294	  # safe.directory advice all run -- writes to git's global config file, and
295	  # with no ~/.gitconfig present git picks the XDG path and then cannot take
296	  # its lock inside /nix/store ("could not lock config file ...: Read-only file
297	  # system"). Git reads both files, so an empty ~/.gitconfig moves the write
298	  # target off the symlink without hiding anything: the store file still
299	  # supplies everything programs.git sets, and a key written here overrides it,
300	  # visible in `git config --list --show-origin`.
301	  home.activation.gitconfigSeed = lib.hm.dag.entryAfter ["writeBoundary"] ''
302	    [ -e "$HOME/.gitconfig" ] || install -m 0644 /dev/null "$HOME/.gitconfig"
303	  '';
