330	  programs.zsh = {
331	    initContent = ''
332	      setopt HIST_FCNTL_LOCK
333	      setopt HIST_IGNORE_DUPS
334	      setopt HIST_IGNORE_SPACE
335	      setopt SHARE_HISTORY
336	
337	      export STARSHIP_CONFIG=~/.config/starship.toml
338	      export ZELLIJ_CONFIG_DIR=~/.config/zellij
339	      export COLORTERM=truecolor
340	      # Grok's counterpart to the `--effort max` on the claude wrapper. A
341	      # GROK_CONFIG overlay rather than a config file: Grok deletes
342	      # ~/.grok/managed_config.toml whenever it refreshes its model catalog,
343	      # so the env is the durable slot. See home/grok.nix.
344	      export GROK_CONFIG=${lib.escapeShellArg grok-cfg.envOverlay}
345	      # Auto-compact at roughly 256k tokens of context, matching Codex's literal
346	      # `model_auto_compact_token_limit` in home/codex.nix. Claude separately
347	      # uses a 512k `autoCompactWindow` capacity. Grok takes a percentage of the
348	      # model's window instead of a token count, and `[session]` is not
349	      # overlay-allowlisted, so it arrives as its own env var. See home/grok.nix.
350	      export GROK_AUTO_COMPACT_THRESHOLD_PERCENT=${toString grok-cfg.autoCompactThresholdPercent}
351	      export BROWSER=open-browser
352	      export EDITOR=micro
353	      # `entire login` defaults to the OS keyring via the D-Bus Secret Service.
354	      # WSL has a session bus but nothing provides org.freedesktop.secrets, so
355	      # the token write fails ("The name is not activatable") and the login is
356	      # thrown away. Persist to ~/.config/entire/tokens.json (0600) instead.
357	      export ENTIRE_TOKEN_STORE=file
358	      export USE_GKE_GCLOUD_AUTH_PLUGIN=True
359	      export MANPAGER="sh -c 'col -bx | bat -l man -p'"
360	      init-gh
361	      eval "$(starship init zsh)"
362	
363	      # Auto-attach to zellij session (or start one) unless already inside zellij
364	      if [ -z "$ZELLIJ" ]; then
365	        session-picker; exit
366	      fi
367	      eval "$(fzf --zsh)"
368	      eval "$(zoxide init zsh)"
369	
370	      echo -e "\033[1;34m"
371	      echo " _   _     _               "
372	      echo "| |_| |__ (_)_  _____  ___ "
373	      echo "| __| '_ \| \ \/ / _ \/ __|"
374	      echo "| |_| | | | |>  < (_) \__ \\"
375	      echo " \__|_| |_|_/_/\_\___/|___/"
376	      echo -e "\033[0m"
377	
378	      # Yazi wrapper for cwd syncing
379	      function yy() {
380	        local tmp="$(mktemp -t "yazi-cwd.XXXXXX")"
381	        yazi "$@" --cwd-file="$tmp"
382	        if cwd="$(cat -- "$tmp")" && [ -n "$cwd" ] && [ "$cwd" != "$PWD" ]; then
383	          builtin cd -- "$cwd"
384	        fi
385	        rm -f -- "$tmp"
386	      }
387	
388	      # Set pane title to repo:branch or cwd (picked up by Zellij)
389	      _set_pane_title() {
390	        local title
391	        local repo
392	        repo=$(git rev-parse --show-toplevel 2>/dev/null)
393	        if [[ -n "$repo" ]]; then
394	          local name branch dirty
395	          name=$(basename "$repo")
396	          branch=$(git branch --show-current 2>/dev/null)
397	          [[ -n $(git status --porcelain 2>/dev/null | head -1) ]] && dirty="*"
398	          title="''${name}:''${branch}''${dirty}"
399	        else
400	          title="''${PWD/#$HOME/~}"
401	        fi
402	        print -Pn "\e]2;''${title}\a"
403	      }
404	      precmd_functions+=(_set_pane_title)
405	
406	      # Emacs mode (enables Ctrl+A/E/K/U/W/R/L, Alt+D/B/F, etc.)
407	      bindkey -e
408	
409	      # Word navigation
410	      bindkey '\e[1;5D' backward-word          # Ctrl+Left
411	      bindkey '\e[1;5C' forward-word           # Ctrl+Right
412	      bindkey '\e[1;3D' backward-word          # Alt+Left
413	      bindkey '\e[1;3C' forward-word           # Alt+Right
414	
415	      # Line navigation
416	      bindkey '\e[H'  beginning-of-line        # Home (normal mode)
417	      bindkey '\eOH'  beginning-of-line        # Home (application mode)
418	      bindkey '\e[F'  end-of-line              # End (normal mode)
419	      bindkey '\eOF'  end-of-line              # End (application mode)
420	
421	      # Deletion
422	      bindkey '\e[3~'   delete-char            # Delete
423	      bindkey '\e[3;5~' kill-word              # Ctrl+Delete
424	      bindkey '\e^?'    backward-kill-word     # Alt+Backspace
425	      bindkey '^H'      backward-kill-word     # Ctrl+Backspace (WT sends bare ^H)
426	
427	      # History
428	      bindkey '\e[1;2A' up-line-or-history     # Shift+Up
429	      bindkey '\e[1;2B' down-line-or-history   # Shift+Down
430	      bindkey '\e[1;2D' backward-word          # Shift+Left
431	      bindkey '\e[1;2C' forward-word           # Shift+Right
432	    '';
